        @test rr.ivpa == 1
        @test rr.nb === nb2
        @test rr.B === B2

        rr = ReturnsResult()
        @test isnothing(rr.ts)
        @test isnothing(rr.nx)
        @test isnothing(rr.X)
        @test isnothing(rr.nf)
        @test isnothing(rr.F)
        @test isnothing(rr.iv)
